(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,53615,e=>{"use strict";var l=e.i(843476),i=e.i(811337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,l.jsxs)(c,{children:[(0,l.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,l.jsxs)(d,{children:[(0,l.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,l.jsx)(n.p,{children:(0,l.jsx)(n.strong,{children:"Джулианна Мэйсон | Julianne Mason"})}),(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"«Джон Конрад», «Джонни» — фальшивое имя и его сокращение, используемые при жизни для прохождения службы в морской пехоте;"}),"\n",(0,l.jsx)(n.li,{children:"«Джилл», «Джилл Конрад» — смешение настоящего и фальшивого имён от сослуживцев;"}),"\n",(0,l.jsx)(n.li,{children:"«Капрал Конрад», «Капрал» — обращение от командования при жизни;"}),"\n",(0,l.jsx)(n.li,{children:"«Капрал Мэйсон» — «если тебе нужны формальности»;"}),"\n",(0,l.jsx)(n.li,{children:"«Снейк», «Биг Босс» — от грешников помоложе, в связи с её фальшивым именем и отсылками к видеоиграм;"}),"\n",(0,l.jsx)(n.li,{children:"«Мантикора» — по расовой принадлежности."}),"\n"]})]}),(0,l.jsx)(h,{title:"Возраст",children:(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"прожитый на земле: 34 года."}),"\n",(0,l.jsx)(n.li,{children:"дата рождения — 28 марта 1935 года. | смерти — 29 марта 1969 года."}),"\n",(0,l.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 49 лет"}),"\n"]})}),(0,l.jsx)(h,{title:"Пол",children:(0,l.jsx)(n.p,{children:"Женский"})}),(0,l.jsxs)(h,{title:"Раса",children:[(0,l.jsx)(n.p,{children:"Мантикора."}),(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"Она была типичным солдатом во время войны во Вьетнаме. Какой бы сильной личностью она ни была, этот адский миксер перемолол её, не оставив и следа от той Джилл, какой она была в молодости. Чем больше она теряла друзей, тем больше она была подвержена вспышкам ярости. После смерти сержанта она окончательно ожесточилась, не гнушалась казнями мирного населения по малейшим подозрениям в сотрудничестве с Вьетконгом, а также окончательно отстранилась психологически от окружающих её людей."}),"\n"]})]})]})}),(0,l.jsxs)(r,{title:"Психологический профиль",children:[(0,l.jsx)(r,{title:"Характер",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"В конце своей жизни Джилл была сломлена окончательно. Это было ключевым фактором определения её как мантикоры. И довольно необычным оказался тот факт, что не столько характер определял расу в новом мире, сколько раса Джилл в какой-то мере определила её нынешний характер. Так уж получилось, что последствия существования в качестве мантикоры вызывали у неё постоянные боли, тошноту, в редких случаях доходило до частичного паралича. Это вызвало раздражительность у Джулианны. Она прекрасно скрывает свой гнев, сдерживает его до самого последнего момента, слишком хорошо понимая, как легко ей будет заиграться и потерять контроль, если она сорвётся. Уж кому, как не ей знать, насколько страшна она в гневе. Стоит её вывести из себя, как перед глазами буквально возникает красный туман, и её место в голове занимает нечто, требующее крови, смерти, страданий. Для самой Джилл это крайне неприятное состояние, и его она желает избегать любыми средствами. Но стоит понимать, что задача это довольно непростая, особенно в условиях Энкража, где различные сумасшедшие, мрази и различные неприятные по своей натуре личности, как правило, задерживаются на дольший срок, нежели приличные, неконфликтные грешники."}),(0,l.jsx)(n.p,{children:"Раны, оставленные войной во Вьетнаме, всё ещё свежи, несмотря на прошедшие десятилетия. Выражается это не только в неприятных воспоминаниях девушки - она иногда может и вовсе полностью уйти в себя, особенно часто такое происходило, когда она рассказывает истории."}),(0,l.jsx)(n.p,{children:"Это уже для многих не в новинку, что она может заговориться, и взгляд её постепенно начнёт становиться отстранённым, голос затихать, речь переходить постепенно в бормотание, что иногда и вовсе не разобрать, а сама Джилл перестаёт реагировать на окружающий её мир. Воспоминания столь сильны, что иногда она переживает заново некоторые моменты из её жизни. Особенно часто к ней приходят смерти её друзей. Подрыв Гарри на растяжке. Ночной штурм их лагеря. Грубо прерванное северовьетнамской армией празднование Тет в Хюэ. И самое отвратительное - та самая засада Вьетконга. Те долгие, мучительные дни в плену. Пытки. Смерть капитана Хопкинса, медленная, мучительная смерть. О, в эти моменты её лицо начинает перекашивать от ужаса, затем - бессильной злобы. Иногда доходит до слёз, но гораздо реже, чем раньше."}),(0,l.jsx)(n.p,{children:"Она терпеть не может, когда оскорбляют её старых сослуживцев. Джулианна в гробу видала всех пацифистов, всех, кто в конфликте во Вьетнаме выступал на стороне Северного Вьетнама, кто высказывается в пользу коммунистов и кому просто кажется смешным подёргать за эти ниточки мантикоры, желая посмотреть, что же будет. И они, и Хранитель убеждались - будет плохо. Её бесят её боли, параличи, онемения. Из-за них она чувствует себя беспомощной старухой во время каждого такого приступа - и это слишком уж бьёт по её самооценке. Её бесят излишне шумные и шаловливые личности, которые привыкли тыкать палкой спящего медведя и убегать, разозлив его. Её раздражает один только вид азиатов, а вьетнамцы и вовсе могут выбесить одним фактом того, что они смеют стоять перед ней. Джилл раздражается и из-за слишком мятежных и, опять же, громких личностей. Или излишне приставучих. Как вы уже наверняка поняли, вывести из себя мантикору не слишком-то и сложно."}),(0,l.jsx)(n.p,{children:"Но что если на секунду отодвинуть в сторону ту сторону Джилл, что показывается, если разозлить её? Увы, даже тогда на ней будет маска. Походка её медленна, и смотрит она на других своим единственным глазом свысока. Она никогда не ставила себя так высоко - эта манера держать себя ей скорее пришла от кошачьих. Взгляд её обычно печален - но нередко, хоть она и сама того далеко не всегда хочет, смотрит на других мантикора с каким-то презрением. По крайней мере, на незнакомцев. Тех, с кем ей не довелось познакомиться поближе, Джулианна старается держать на расстоянии. Нет, не в прямом смысле - она просто дистанцируется, очень не желая раскрываться. И всё же завоевавшие доверие капрала знают её как грешницу довольно таки компанейскую. Пусть она теперь далеко не всегда может исполнять роль души компании, как когда-то, но всё же даже сейчас Джилл не прочь пошутить, посмеяться, поболтать с теми, с кем ей комфортно. У неё всегда есть истории о войне - множество историй, как полных героизма и отваги американских солдат, так и кровавые, мрачные рассказы об их падении. Она хороший собутыльник, особенно если ей наливать виски, Джек Дэниелс, верного друга как при жизни, так и здесь, в якобы аду. Алкоголизм всё же является её довольно заметной чертой. Но самая главная черта Джулианны - верность тем, кого она считает важной для себя. Хоть ей и не приходилось ни разу, она более чем готова заградить своим покорёженным телом друга, разыскиваемого Сталкером. Тем более что для воспитанной отцом-солдатом и американской армией Джулианны авторитет есть лишь один в этом мире - Хранитель, контракт с которым сделал его де-факто командиром для мантикоры."}),(0,l.jsx)(n.p,{children:"Есть ещё одна мелкая, но любопытная деталь. Джулианна не любит, когда её называют по её полному имени. Не то чтобы это её злило так же сильно, как оскорбление её сослуживцев, или её боли - ей просто в такие моменты жутко некомфортно."}),(0,l.jsx)(x,{children:(0,l.jsx)(n.p,{children:"Джилл. Капрал Мэйсон или же капрал Конрад, если тебе так нужны формальности. Я тебе в лицо этот виски вылью, если ты меня ещё раз назовёшь этим именем"})})]})}),(0,l.jsx)(r,{title:"Страхи",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Плен",children:(0,l.jsx)(n.p,{children:"Хоть в Энкраже на данный момент и не происходит никаких войн, Джилл до жути боится попасть в плен во второй раз в своей жизни. Первое такое попадание уже оставило на её душе страшную рану - вряд ли она будет адекватно себя вести во втором плену, пусть даже в самых мягких условиях."})}),(0,l.jsx)(h,{title:"Звуки гусеничной техники",children:(0,l.jsx)(n.p,{children:"Звуки движения гусеничной техники - здесь уже срабатывает рефлекс, от которого избавиться для Джулианны ещё не скоро получится. Если она не может найти глазами технику с родной американской звездой, эти звуки заставят её искать укрытие в панике - и лишь потом уже проверять, что да как."})}),(0,l.jsx)(h,{title:"Встреча знакомых лиц",children:(0,l.jsx)(n.p,{children:"Встретить знакомые лица здесь. Вот здесь настоящая ирония - она вроде бы на деле хочет этого. Повидаться ещё раз со старыми знакомыми кажется столь заманчивой перспективой - но с другой стороны ей страшно даже взглянуть им в глаза. К тому же, с этим страхом связан другой..."})}),(0,l.jsx)(h,{title:"Сослуживцы-Пустые",children:(0,l.jsx)(n.p,{children:"Узнать, что кто-то из её сослуживцев стал одним из Пустых. Если это и правда произошло, она бы предпочла не знать - это её, скорее всего, просто добьёт."})}),(0,l.jsx)(h,{title:"Потеря близких",children:(0,l.jsx)(n.p,{children:"Потерять тех, кто стал ей близок - на этот счёт у Джилл так же есть ужасная травма. Она только недавно вновь научилась подпускать к себе людей - и ей явно не хочется, чтобы история с ними пошла по второму кругу."})})]})}),(0,l.jsx)(r,{title:"Мечты, цели",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Ей хотелось бы вновь повидаться со своими сослуживцами. Ещё разок выпить с ними, сыграть в покер, как в старые добрые времена. Подшутить над Гарри и Стэном в последний раз, и самое главное — нормально попрощаться с ними. Без этого она не сможет их отпустить, увы."}),(0,l.jsx)(n.p,{children:"Закрепиться в этом мире. Она уже повидала всё, всё сделала в том мире, что могла только захотеть, и съела после смерти свой утешительный тортик. Возвращаться туда ей не хочется — а здесь у неё есть шанс найти применение своим навыкам. Или умереть — по настоящему."}),(0,l.jsx)(n.p,{children:"Всё-таки выпить с Хранителем — а чего вы ожидали от грешной алкоголички?"}),(0,l.jsx)(n.p,{children:"Заставить Уилла вспомнить, кто он такой. Без этого одна из её главных целей не может быть достигнута. Совсем. Да и других, если они уже переродились, тоже хорошо бы — правда, она даже не знает, что с ними сейчас, и иногда она даже не уверена, что хочет знать."})]})}),(0,l.jsx)(r,{title:"Биография (при жизни)",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Родители Джулианны были юны — слишком юны, чтобы иметь ребёнка, за что их очень много осуждали. Соединённые Штаты Америки тогда ещё не были так помешаны на толерантности. Отнюдь, тогда сексистские и расистские настроения всё ещё процветали, а одними из величайших ценностей считались традиции. Тем не менее, первые пару лет она жила в родительской любви и заботе. Но затем случилось непоправимое. Нет, никто не умер - но мать Джулианны завела интрижку на стороне, и отец это быстро обнаружил. Дочка осталась при нём - своим ребёнком он дорожил, и воспитание он старался дать настолько хорошее, насколько только мог. Именно он, её молодой отец, учил её упорно двигаться к своей цели, несмотря ни на какие препятствия на её пути. Он даже не представлял, как глубоко этот его урок врезался в душу Джилл. В конце-концов, отец для неё был самым настоящим авторитетом и, пожалуй, единственным примером для подражания."}),(0,l.jsx)(n.p,{children:"Как и у многих детишек в то время, у Джулианны разлука с отцом случилась из-за войны. Ему пришлось оставить дочку дома, в Айова-сити. Она училась под присмотром бабушки и дедушки-инвалида, что уверяли, что с её любимым папой будет всё в порядке. Пока она училась - Мэйсон старший проходил интенсивные тренировки, чтобы стать рейнджером. Конечно, не сразу - сначала его записали в 34 Пехотную Дивизию, и лишь потом он был отобран среди добровольцев. Он прошёл через Северную Африку, повоевал в Италии, был переведён во Второй Рейнджерский Батальон, брал Пуант-дю-Хок и был ранен во время одной из немецких контратак. Он вернулся домой в конце 1944 года."}),(0,l.jsx)(n.p,{children:'Вернулся с парой мелочных немецких сувениров, среди которых была и металлическая фляжка немецкого солдата. Ту они вычистили хорошенько, и с тех пор девчонка не расставалась с ней. Стоило признать - внимание мальчишек она явно привлекла. И ей точно пришлось научиться драться, чтобы этот сувенир, возведённый ей в ранг реликвии, не отобрали те, что понаглее. Уже было понятно - как девочку Джилл воспитать будет теперь крайне трудно. Отцу в принципе было трудно вернуться к самостоятельному воспитанию и обеспечению дочери - но он всё же взял на себя эту ношу. Со временем он просто решил ей позволить держаться с мальчишками, решив, что она со временем это просто перерастёт. Может, так бы и случилось в жизни Джулианны, если бы не его истории. Истории о войне сначала были героическими - но затем, когда девочка росла, он добавлял всё больше "взрослых", неприятных деталей. Но ещё с первых рассказов ей захотелось быть солдатом, как папа, и никакая жестокая правда не могла переубедить юную мисс Мэйсон.'}),(0,l.jsx)(n.p,{children:"Из Айовы в 50-х годах они переехали в Нью-Йорк. Как говорил отец, будет трудно, но они справятся. В столице им найдётся место. И он не соврал. Послевоенная жизнь в новом месте была действительно трудной, но всё же они удивительным образом держались на плаву. Пожалуй, даже слишком удивительным - жили они всё же даже не в бедности, а денег Мэйсон старший получал не так уж и много. Официально. Он занимался перевозкой грузов после войны - и он привык не задавать клиентам лишних вопросов. К тому времени, несмотря на все усилия правоохранительных органов, ценность таких личностей нельзя было переоценить. Особенно для определённой группы италоамериканцев, кому как раз не хотелось бы получать вопросов о грузе - но хотелось бы иметь возможность перемещать его из точки А в точку Б. В этом городе девушка и закончила свою учёбу. Увы, в то время женщины имели не так много вариантов работы. Секретарь в очередном офисе. Совсем не интересно. Да и за фляжку, что Джилл так и не перестала носить с собой повсюду, её по головке не гладили - но работа есть работа. Деньги есть деньги."}),(0,l.jsx)(n.p,{children:"А настроения шли не самые мирные. Холодная война с СССР. Коммунисты теперь считались плохими - чёрт знает почему, но считались. И это было далеко не мирное время. Гонка вооружений - одно дело. Другое - когда не за горами намечается война. В начале шестидесятых уже было ясно, что она будет. Нет, не с русскими, понятное дело - слухи шли о двух, казалось бы, совершенно левых странах: Южном и Северном Вьетнаме. В ту пору шла активная антикоммунистическая пропаганда. Именно тогда в Джулианне начали просыпаться её старые мечты - стать солдатом, быть такой же героиней Америки, как и её папочка. Но тогда женщин брали лишь как военных медсестёр. Этот вариант совсем не устраивал её. Медсёстры не стреляли по врагам её родной страны на фронте, не защищали её союзников. Взрослой даме захотелось исполнить детские мечты, и альтернативами ограничиться она не была готова. Даже если препятствия казались непреодолимыми."}),(0,l.jsx)(n.p,{children:"Весной 63 года отец Джилл слёг в больницу. Здесь стоит отметить, что он начал курить во время войны, надеясь успокаивать этим нервы, и с тех пор он каждый день курил минимум по пачке сигарет в день. От рака лёгких врачи не имели никакого средства. Его единственная дочка его очень часто навещала после работы, по выходным - но сделать для него могла не так уж много. Она могла лишь поклясться ему, что он сможет гордиться своей дочкой, наблюдая за ней с небес. Тогда же она услышала и признания от него и признание в связях с мафиозной семьёй. Сказал, что Джилл должны будут занести плату за последний его груз - и попросил, чтобы она не связывалась с ними, поскольку последствия могут быть не лучшими."}),(0,l.jsx)(n.p,{children:"Тем не менее, она слишком хорошо помнила его же урок. Нужно упорно двигаться к цели, невзирая ни на какие препятствия. После смерти отца ей действительно занесли плату - и она смогла договориться о встрече с доном ради просьбы, просто благодаря верности её отца и довольно немалой пользы."}),(0,l.jsx)(n.p,{children:"И вот она, тропа к цели, какую она искала - мафия могла организовать ей и поддельные документы, и пристроить к своему человеку аж в Корпус Морской Пехоты. Не бесплатно - но она готова была продать машину отца, отдать все свои сбережения, своё наследство, дабы получить нужную сумму. Оставила себе лишь дом, дабы было куда возвращаться с победой после войны, что уже началась. Наверняка ведь Соединённые Штаты вмешаются, придут на помощь своим южновьетнамским союзникам. Конечно, всё было не так просто - ей пришлось ещё ждать и делать всё, что скажут, дабы протиснуться. Коротко подстричь волосы, носить обмотки, дабы максимально скрывать свою грудь, заучить каждую фразу, какие ей нужно было говорить, дабы её узнали, как нужную личность и позволили попасть в ряды новобранцев, и самое главное - запомнить своё новое имя - Джон Конрад. Ей повезло ещё что налысо бриться не заставили. А попасть в ряды морпехов США - это пройти не только через бюрократическую часть, но и пережить действительно адскую учебку."}),(0,l.jsx)(n.p,{children:"Крики. Унижения. Тяжёлые тренировки. Сержант-инструктор по строевой и боевой подготовке, их командир взвода, не давал спуску единственной девушке в их рядах. Его нельзя было обмануть, и, сказать честно, тот надеялся вытравить её, пропуская через весь тот ад, что и других, и даже немного больше. Но Джилл отличилась жутким упорством - и тем фактом что она на фоне дебилов Макнамары, что шли в армию чуть ли не потоком, казалась чуть ли не образцовым солдатом, несмотря на свой пол, заставляя всё же смириться с этой особой. Не каждый взрослый парень, стоявший там вместе с на первый взгляд хрупкой девушкой в строю, мог выдержать те же эмоциональные и физические нагрузки, что и она. До сих пор она с дрожью вспоминает, как один из новобранцев застрелился в душевой из собственной винтовки, не вытерпев постоянных унижений. Он не мог понять вовремя, что армейская жизнь не для него. Он сломался."}),(0,l.jsx)(n.p,{children:'Нельзя представить Соединённые Штаты без патриотизма. В 1965 году этим духом прониклись все - и простые люди, и солдаты армии США, и SEAL, "Морские Котики", и, тем более, бравые морпехи. Для девушки состоялось боевое крещение во время операции Старлайт - пуля из вьетконговского Мосина оцарапала ей плечо. Конечно, она была в порядке - но всё же девушка через это прошла, и это помогало солдатам видеть её как свою. Как и во время учебки, здесь она пол свой могла прятать лишь для официальных документов, но никак не для живых людей. Впрочем, они привыкли. Да и Джилл Конрад звучало для них неплохо. Фальшивая фамилия к ней просто прилипла. Но Старлайт - это только начало. Это была не та война, где больше всего крови проливалось в крупномасштабных сражениях.'}),(0,l.jsx)(n.p,{children:"Хоть Джулианна и не была самой опытной в своём взводе - она была самой старшей. Это быстро сделала её если не мамочкой, то старшей сестрой для остальных солдат. Первые несколько месяцев беды их обходили стороной. Она могла спокойно шутить вместе с Эдди, задирать вечно недовольного Стэна и подкалывать стеснительного Гарри, даже не задумываясь о том, что их может скоро и не стать. В конце-концов, что может для них пойти не так в этой явно победоносной войне?"}),(0,l.jsx)(n.p,{children:"Как же зря она так думала."}),(0,l.jsx)(n.p,{children:'Засады Вьетконга были не единственной напастью для них. В джунглях их винтовки были сами по себе неудобны, здесь было сыро, грязно… И полно ловушек. Помните, упоминали стеснительного, немного трусливого паренька по имени Гарри? Его из-за его натуры любили подталкивать к Джилл, настаивая на том, чтобы он уже подкатил к ней. Та об этом прекрасно знала и по доброму подкалывала беднягу. Иногда она могла после потрепать его по голове и сказать, чтобы не обращал на этих дебилов внимания. Тот иногда мог приободриться - а иногда это ему не помогало. Вот только в тот день простым "потрепать по головке" ему уже было не помочь - он задел растяжку. Оглушительный взрыв. Крики боли, что едва прорывались сквозь писк в ушах, чуть ли не разрывали душу девушки - а от увиденного она не могла отвести полных ужаса глаз.'}),(0,l.jsx)(n.p,{children:'Гарри, тот самый Гарри, который ещё недавно мог бы смутиться от одной немного пошлой шутки, сейчас лежал в грязи с выпученными от страха глазами, и орал. Орал. Рыдал. Кричал, что он не чувствует ногу. Просил, требовал вернуть ему его конечность, что сейчас лежала поодаль, вся окровавленная. Она смотрелась так жутко отдельно от своего хозяина. Почти так же жутко, как и кровавое месиво на её месте у её рыдающего, слабеющего от жуткого кровотечения хозяина. Медик не мог ему ничем помочь. Никто не мог - скоро послышались шаги, пришлось рассредоточиться, приготовиться к перестрелке с противником. Вьетконг. Их уже успели окрестить "гуками". О раненном, казалось, уже просто-напросто забыли. Вспомнили лишь когда они отбились, заставив партизан отступить. К тому моменту Гарри уже затих. Совсем. Он уже покинул этот мир.'}),(0,l.jsx)(n.p,{children:"Она ничем не могла ему помочь"}),(0,l.jsx)(n.p,{children:'Грубо сделанный крестик, на который повесили винтовку, да надели шлем - вот и всё украшение для наспех сделанной могилки солдата. Вроде бы Джулианна и ранее видела смерти за войну - но сейчас она начала осознавать, во что же она влипла, гоняясь за глупой мечтой. Но она всё ещё старалась быть весёлой девушкой, душой компанией, дабы не давать падать духом остальным. Ей нужно было оставаться сильной. В конце-концов, она была дочкой Уилла Мэйсона, рейнджера, прошедшего через самый настоящий ад. Чем она хуже своего отца? Чего у него было такого, чего не было у его дочки? Вскоре их перевели в район Дананга, где их задачей было постепенно зачищать местность от сил Вьетконга. В доктрине "Найти и уничтожить", увы, мало поднимается вопросов на щекотливую тему - а как быть с гражданскими, подозреваемыми в содействии НФОЮВ?'}),(0,l.jsx)(n.p,{children:"Изначально, конечно же, девушка не одобряла слишком радикальных действий. Она поддерживала своего сержанта, не раз вступавшего в конфликт с избивающими местных жителей группами морпехов - и многие солдаты из её отряда вставали на её сторону. Джилл заработала себе немалый авторитет, показав немалую стойкость и продолжая пытаться удержать боевой дух шокированных столь жестокой смертью товарища солдат. Она напоминала, зачем они вообще здесь, влезала в драки."}),(0,l.jsx)(n.p,{children:"Приходилось даже махать оружием, и именно в эти моменты её сердце колотилось, как бешеное. Она боялась каждый раз перестрелки со своими же - и каждый раз она всё-таки не начиналась. Всё обходилось. Вьетконговские растяжки они научились всё же находить, и в целом, двигаться гораздо осторожнее. Увы, без потерь всё равно не обходилось. Время от времени в их стане начали появляться раненные - один раз Джилл приходилось вытаскивать сержанта буквально на своих плечах. И, увы, не все выбирались из боёв живыми. Но это уже не было таким шоком для девушки, как смерть Гарри."}),(0,l.jsx)(n.p,{children:"Перед глазами изредка мелькало его перекошенное от ужаса лицо."}),(0,l.jsx)(n.p,{children:"Примерно зимой была ранена в грудь и сама Джулианна. К счастью, ранение не было слишком серьёзным - но ей пришлось отлёживаться в госпитале аж до конца весны 1966 года."}),(0,l.jsx)(n.p,{children:"На неё в какой-то мере давило чувство беспомощности - а так же волнение за сослуживцев. Она успела привязаться к этим глупым солдатикам. Тем не менее, её единственным развлечением были другие такие же раненные, смотревшие на женщину в солдатской форме, словно на диковинку, да радио, по которому шли новости, да играла музыка. Впрочем, если уж быть совсем честными - прекрасный пол, сражающийся с оружием в руках - действительно нечто неслыханное для американцев в те времена. Но тогда пока что она не задавалась вопросом, почему она здесь, на войне. Пока что для неё не было ничего непреодолимого. Она врала солдатам о своём имени, не говоря настоящего. Отказывалась говорить, как попала сюда, ведь ей не хотелось подставлять тех, кто позволил ей сюда попасть. От неё так и не получили никакой интересной истории о том, как женщина со странным именем Джон Конрад попала в ряды морской пехоты армии США. Лишь отмашки, да очевидные враки. Должны были отправить назад, домой, для разбирательств - но из-за положения на фронте на неё просто закрыли глаза. Как ей казалось, из-за положения на фронте. Правду же знают лишь медики вместе с их командующим офицером - и, возможно, кто-то ещё, кого она учесть не могла."}),(0,l.jsx)(n.p,{children:'Вернулась к своим Джилл довольно таки вовремя - многие из раненых ранее уже вернулись в строй. Кроме пары человек - кто-то уже был не дееспособен, а кто-то скончался там, в госпитале. Без шутника Эдди было не так весело проводить время, увы, но он хотя бы вернётся домой. Инвалидом, но вернётся. Везунчик. Но зато у них всё ещё была душа компании Джилл Конрад, да этакий отец всего взвода - сержант Уилл Стоун. Она продолжала делать то, что должна. Вплоть до операции "Гастингс". Именно во время этой операции ей пришлось столкнуться с чем-то посерьёзнее гуков на деревьях - Северновьетнамская регулярная армия. Это не было полномасштабным сражением - скорее, серия мелких стычек. Мелких, ожесточённых стычек. Казалось, в эти дни она не слышала ничего, кроме стрельбы в джунглях Вьетнама. Стрельбы - и взрывов. Именно тогда ей предстояло узреть бомбардировки напалмом. Именно тогда, когда ей хотелось, чтобы эти чёртовы джунгли, полные ловушек и узкоглазых, просто сгорели к чёрту. Прекрасное зрелище. Прекрасное, но при этом ужасающее. Им нужно было уйти, чтобы не сгореть вместе с гуками. Но в целом - выстрелы, взрывы продолжались до самого конца операции. В какой-то момент их просто перебросили на другой участок.'}),(0,l.jsx)(n.p,{children:"В 1967 году им подвезли новые игрушки. Винтовки М16А1, уже исправленные на опыте других подразделений. Многим смена оружия не понравилась - они слишком привыкли к своим М14 и, в некоторых случаях, стареньким Томпсонам, но для Джилл это было самое настоящее облегчение. Удобная, с меньшей отдачей, точная и, вопреки злым языкам и явно сфальсифицированным в пользу старушки под .308 испытаниям, достаточно надёжная винтовка ей была как раз кстати. Примерно в то время для них наступило временное затишье. Они тренировали ополчение, сидели на стрельбище, патрулировали лагерь и проводили друг с другом время. Именно тогда Уилл познакомил девушку с Джеком Дэниэлсом. Виски. Хороший виски. Ей как раз нужно было что-то, что поможет справляться с нарастающим грузом на её плечах. Каждый килограмм, будь то физический или метафорический, что она могла сбросить, становился столь необходимым облегчением."}),(0,l.jsx)(n.p,{children:"Слишком много умерло на её руках."}),(0,l.jsx)(n.p,{children:"Ворчливый Стэн оставался тем же ворчуном - но к нему уже давно привыкли. Он влился в компанию, проявил себя, как голос разума в компании запивающих стресс и не особо адекватно рассуждающих на фоне происходящего солдат."}),(0,l.jsx)(n.p,{children:"Над ним подшутить разок-другой для Джулианны, уже рядового первого класса, было святым делом. Он прошёл уже два года войны вместе с остальными солдатами. Прошёл через самые жестокие бои, считался уже одним из старичков. Увы, затишье не продлилось долго. После очередного мелкого рейда на лагерь Вьетконга и помощи деревне, которую собирались вычистить за содействие силам США, они вернулись в свой лагерь. Ночью они не спали - капитан Хопкинс решил задержать их, дабы дать им отличную новость - на празднование этого праздника Тет, вьетнамского Нового Года, они отправятся в Хюэ. Вот только эта отличная новость была прервана резко вбежавшим вьетконговцем. Стэн умер на месте. Очередь из ППШ прошила его насквозь. Немного подвыпившая Джилл была в ярости. Её она выпустила на вторгшемся гуке, разрядив в него весь магазин пистолета, не прекращая стрелять даже когда тот уже падал замертво с дырой во лбу."}),(0,l.jsx)(n.p,{children:"Даже у самых крепких вещей имеется та точка, после которых давить на них просто-напросто опасно. Они ломаются. До той точки довели и Джулианну. После того, как они отбили штурм, они стали восстанавливать лагерь. Девушка уже не была той улыбчивой, немного игривой особой, что не давала остальным впасть в уныние. Лицо её было мрачно, а взгляд её словно смотрел на две тысячи ярдов, игнорируя любого, кто встанет на его пути. Ей достаточно было оглядеться, чтобы понять, что оставшиеся морпехи ей толком-то и не знакомы. За исключением пары человек - сержанта Стоуна и капитана Хопкинса. И ведь она уже не могла даже гарантировать что с ними всё будет в порядке - проклятые узкоглазые могли без проблем проникнуть даже в защищённый лагерь."}),(0,l.jsx)(n.p,{children:'Возможно, это была настоящая влюблённость. Возможно, она просто так сильно зацепилась за одного из последних выживших, что уже готова была делать что угодно, чувствовать что угодно, лишь бы заставить его дойти до конца в этой войне. Сержант Уилл Стоун. Сложно было сказать, насколько оно было взаимно. Для откровенностей времени, увы, не хватало, не в условиях войны. Попутно с этим она отдалилась от остальных, стала холодна с "зеленью", с южновьетнамскими солдатами, с репортёрами, которым запретили снимать девушку в солдатской форме. Пришли и новости о том, кто это сделал - один из якобы ополченцев из деревни, которых тренировали в лагере. Всё-таки мирные жители на стороне Вьетконга - суровая реальность. Это серьёзно подорвало доверие к тем, кого Джилл защищала. Возможно, именно потому она не хотела больше вмешиваться, видя, как другие морпехи откровенно издеваются над местными, забирая подозреваемых в содействии коммунистическим партизанам. А может, это потому что ей было просто плевать. Уже было совсем не до каких-то южновьетнамских слабаков. Война перестала быть для неё защитой союзников - теперь уже дело было в сведении личных счётов. Вьетконг заплатит за всех, кого он отнял у Джулианны.'}),(0,l.jsx)(n.p,{children:"Впрочем, был праздник, который обе стороны чтили свято. Во время уже упомянутого ранее Тет обе стороны заключали перемирие, дабы иметь возможность провести столь важный для Вьетнама праздник в мире и спокойствии. Как Хопкинс и обещал, они были расквартированы в Хюэ. Многие солдаты висели в преддверии праздника по борделям. Джилл не была исключением - но лишь потому что в одном из них так же был ещё и бар. Напиться виски, приставать к сержанту, и по пьяни дать клятву, что она никому больше не даст умереть. Она явно перебрала с алкоголем в тот день. Но к самому празднику, к её огромному счастью, она была трезвой, как стёклышко."}),(0,l.jsx)(n.p,{children:"К счастью - не потому что ей предстояло выслушивать от других командиров, как её собираются отправить домой, поскольку она девушка, и там сдать её в полицию за подделку документов. Нет, это дело было замято из-за другого, гораздо более страшного происшествия. Вероломное нападение северовьетнамской армии. Нарушение перемирия, первое за историю всей этой войны. Они не были готовы, никак не могли быть. Им пришлось буквально пользоваться тем, что нашли на трупах, дабы с боем пробиться к машине и выжить."}),(0,l.jsx)(n.p,{children:'И вновь рядовая первого класса тащила на себе израненного Уилла, отстреливаясь из АК, до "Уиллиса". Усадила на пассажирское сидение, завела, поехала в сторону их ставки, пытаясь маневрировать под обстрелом узкоглазых. Она выбралась, но вот сержанта спасти не смогла - тот скончался от полученных ранений, едва его девушка довезла до ставки. И вновь свой гнев она вымещала на вьетнамских солдатах, пытаясь как-то защищать штаб. Увы, им пришлось отступить. Сдержать наступление они никак не смогли - могли лишь отбить этот город в будущем. Не таком и далёком будущем - всего-то пару дней.'}),(0,l.jsx)(n.p,{children:"Как же она их ненавидела..."}),(0,l.jsx)(n.p,{children:"Хуже всего было то, что потери проклятых узкоглазых мразей были велики, но правительство перестало поддерживать продолжение войны. Никто не хотел продолжать сражаться. Джилл начало казаться, что все её предали, покинули, кроме капитана Хопкинса. Капитан был последним, кто ей был знаком с самого начала войны. Он распорядился о выдаче девушке звания младшего капрала. Она получила собственный отряд безымянных для неё солдат в своё распоряжение. Увы, война окончательно ожесточила её. За дисциплиной следила она крайне строго. Собственные подчинённые её боялись - и её бояться научились и местные. Когда-то будучи противницей этих чисток, теперь она сама их устраивала в деревнях, если начинала подозревать чью-то связь с Вьетконгом. Ей было плевать на пол, возраст, на их семьи. На всё. Иногда даже на то, была ли связь на самом деле. Джулианна винила их в том, что она потеряла всех своих старых сослуживцев. Она не смела привязываться к новым - всё равно чёртовы гуки отберут у неё и их."}),(0,l.jsx)(n.p,{children:"Март 1969 года - это время, когда её история подходила к концу. Во время одной из очередных зачисток отряд, возглавляемый капитаном Хопкинсом, попал в засаду Вьетконга. Большая часть была убита - но капитан, Джилл и ещё пара человек были захвачены в плен. Они содержались в узких тоннелях, плохо предназначенных для жизни неподготовленных людей. Их пытали. Много. Жестоко. Капитан был лишён своего мужского достоинства, нескольких пальцев, и в итоге скончался от потери крови. С него перешли на ребят, на саму Джилл. Она была лишена глаза. Её насиловали, пытались выбить информацию - но что может знать о планах американцев младший капрал?"}),(0,l.jsx)(n.p,{children:'Впрочем, ей не было суждено скончаться в плену этих узкоглазых монстров - началась шумиха из-за операции "туннельных крыс". Спецназ занимался чисткой тоннелей - и девушке удалось бежать. К сожалению, её дни были сочтены - она едва не напоролась на одну из самых известных ловушек гуков - колья пунджи. Ей не дал провалиться другой солдатик, вовремя поймав. Увы, ногу они проткнули, хоть и неглубоко. Заражение крови было гарантированно - эти колья измазывали фекалиями. Единственному бежавшему солдату вместе с ней досталось хуже - через пару десятков метров он упал в "мясорубку". Вытащить его уже было нельзя - он потихоньку проваливался, и колья впивались в его тело, превращая его в дуршлаг. Ситуация была хуже некуда - она сейчас была на вражеской территории, посреди извращённого варианта "минного поля" гуков, с АК с полупустым магазином, без всяких карт, а самое главное - с раненной, истекающей кровью ногой, в которой уже наверняка был своеобразный "яд" Вьетконга. Вновь её ждал шок. Шок - а затем отчаяние.'}),(0,l.jsx)(n.p,{children:"Неужели это конец."}),(0,l.jsx)(n.p,{children:'Её подобрал отряд "морских котиков". Уже готовую сдаться, лежавшую на земле. Оказали первую помощь. Обещали вытащить отсюда, дотащили до катера, двинулись по реке и дали в руки оружие. Уже единственный глаз Джилл тогда загорелся в последний раз - загорелся единственным чувством, испытывать которое у неё были силы. Яростью. В ярости она палила по всему, что не имело сходства с американцами, казалось, не обращая никакого внимания на тяжесть пулемёта SEALов. Но патроны были не бесконечными - и, едва коробка с двести двадцать третьими опустела, а потянуться за патронами она уже не чувствовала сил от потери крови, девушка просто легла смирно. Она хотела знать лишь одно - дату. Двадцать девятого марта тысяча девятьсот шестьдесят девятого года Джулианна Мэйсон, по документам числившаяся как капрал Джон Конрад, произнесла свои последние слова. "Видимо, вчера был мой последний день рождения." Она краем глаза увидела, как по ним уже целился вьетконговец с автомата. Хотелось предупредить - но не успевала. Последнее, что она услышала в своей жизни - громкий хлопок.'}),(0,l.jsx)(n.p,{children:"Впрочем, она уже не была против. Ей уже окончательно надоела эта жизнь - досадно лишь что её пришлось отдать этим грязным животным..."})]})}),(0,l.jsx)(r,{title:"Жизнь в Энкраже",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Башня Энкража для неё пролетела незаметно. Она буквально не замечала огромной части того, что здесь происходила, двигалась по инерции вперёд, лишь в крайних случаях с отстранённым видом задумываясь о том, что же от неё вообще требовалось. Джилл продолжала страдать от ран, оставленных на душе этой ужасной войной. Слишком быстро воспоминания пришли к ней. Первыми почему-то были те, о которых ей не хотелось бы вообще вспоминать. Она помнила каждого, кого она потеряла. Каждого, кто отдал жизнь на этой войне. Каждого убитого, заслуживал он того, или нет."}),(0,l.jsx)(n.p,{children:"Вновь её единственный глаз глядел куда-то на две тысячи ярдов, игнорируя всё, что было вокруг неё. Одному Хранителю известно, что творилось с её ядром в процессе. К нему уже вышла уставшая по виду седая девушка с повязкой на той дыре, что была вместо правого глаза. Мантикора. Для многих это был дурной знак - для тех, кто понимал, что это вообще для них значит. А Джилл задавалась лишь одним вопросом, одним-единственным вопросом."}),(0,l.jsx)(n.p,{children:"Почему так болит голова?"}),(0,l.jsx)(n.p,{children:"Ей плевать было на то, что она каким-то образом ещё была жива. На то, что она была в каком-то новом мире, что она изменилась, что ей что-то пытались говорить. Казалось, ей двигали разве что обрезки каких-то инстинктов, и если бы не они, Джилл бы просто свернулась в комочек и умерла ещё раз, теперь уже навсегда. Из её состояния овоща её начала выдёргивать боль. Боль в плечах, боль в спине, боль в её отсутствующем уже долгое время глазу. И как же она раздражала..."}),(0,l.jsx)(n.p,{children:"В свои первые годы Джулианна постоянно колебалась между состояниями абсолютно безразличного создания, не замечающего грешников в упор, и вечно ненавидящей всех стервы, что была буквально в шаге от перерезания глотки любому, кто ей встретится. Кто-то ей посоветовал арену. Это ей даже умудрилось помочь на какое-то время - но мантикора распугала многих дуэлянтов, не только своей скоростью, но и своим диким нравом в бою."}),(0,l.jsx)(n.p,{children:"Ей мало было просто победить в бою - она жаждала убить, растерзать, разорвать на части своего оппонента, отчего нередко её приходилось оттаскивать в конце боя, дабы не пришлось вмешиваться Хранителю. Страдала и репутация сражавшихся с ней - девушка умудрялась побеждать, не имея особых способностей, с одним лишь ножом. И это не было случайности - победы шли целыми сериями, и большая их часть выходила из под контроля. А виной тому - её же боли, что доводили девушку до состояния, в котором сражаться с ней было по меньшей мере глупо. В итоге это стало надоедать Реальтам - дошло до запрета на появление на арене для одноглазой мантикоры. Более-менее брать себя в руки Джилл стала лишь относительно недавно. По крайней мере, она могла идти на контакт, она могла сдерживать свой гнев. Конечно, это не значило, что жизнь стала хотя бы более-менее комфортной. Нет, далеко не комфортной."}),(0,l.jsx)(n.p,{children:"Ей приходилось прикладывать огромные усилия, просто чтобы до следующего своего падения на кровать вести себя нормально, не попытаться никого прибить, не избегать всех подряд, боясь самой себя. Тем не менее, были грешники, что вызывали у неё искреннюю ненависть - и именно из-за них ей пришлось познакомиться поближе с Хранителем. Ох, сколько раз ей приходилось получать по голове и уходить на увлекательную беседу с большим папочкой этого замка просто из-за одной высокомерной дамы-вуивра…"}),(0,l.jsx)(n.p,{children:"И тем не менее, у неё здесь были и те, кому зла она явно не могла желать. В какой-то мере из-за них Джилл и обратилась к Хранителю с предложением. Ещё одна беседа - и с ним был заключён контракт. Она обязывалась слушаться Хранителя, позволяла ему следить за ней, записывалась в ряды его личной армии из одной мантикоры, на случай, если настанет экстренная ситуация, а взамен она получит то, что позволит ей контролировать происходящее с её ядром, а Хранитель будет злобно и с неодобрением смотреть на тех, кто посмеет оскорбить память её покойных сослуживцев…"})]})})]}),(0,l.jsxs)(r,{title:"Дополнительно",children:[(0,l.jsx)(r,{title:"Факты о персонаже",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Судьба старичков",children:(0,l.jsx)(n.p,{children:"Джулианна прожила дольше всех из группы «старичков»: шутник Эдди умер примерно через полтора месяца после своего возвращения домой. Суицид."})}),(0,l.jsx)(h,{title:"Отношение к Хранителю",children:(0,l.jsx)(n.p,{children:"Несмотря на то, что Хранитель часто сдерживал Джилл не самыми мягкими методами, она к нему относится вполне спокойно и даже дружелюбно. До сих пор она иногда пытается его уговорить выпить с ней."})}),(0,l.jsx)(h,{title:"Современные видеоигры",children:(0,l.jsx)(n.p,{children:"Она немного знает о современных видеоиграх, спасибо новеньким грешникам, потому она спокойно реагирует на шутки про её имя, а так же про её фальшивое имя (и его связь с белым фосфором). Что-то она понимает и по поводу Метал Гира со Снейками. Но она до сих пор не может понять сравнений её с персонажем из какой-то мобильной аниме-игры."})}),(0,l.jsx)(h,{title:"Отношение к вьетнамцам",children:(0,l.jsx)(n.p,{children:"Проклятые гуки они и тут есть за что мне всё это."})}),(0,l.jsx)(h,{title:"Воровство с кухни",children:(0,l.jsx)(n.p,{children:"Джилл своровала из кухни больше еды, чем кухня у неё. Тайком не поедала - сворованную пищу она ела открыто и с по кошачьи довольным видом, по крайней мере, когда голова её была в достаточной мере чиста. К слову, она неплохо готовит, но ей обычно слишком лень."})}),(0,l.jsx)(h,{title:"Судьба матери",children:(0,l.jsx)(n.p,{children:"Джулианна никогда не интересовалась судьбой матери. Та, к слову, пыталась узнать хоть что-то о своей дочке в годы войны, но Джилл стала считаться пропавшей без вести из-за того что в армии она была нелегально и под поддельными документами. Умерла она в 1979 году от туберкулёза."})}),(0,l.jsx)(h,{title:"Поражение во Вьетнаме",children:(0,l.jsx)(n.p,{children:"О поражении США в войне во Вьетнаме она узнала в районе 1997 года. Под присмотром Хранителя. К всеобщему удивлению, она хоть и была на грани входа в берсерка, она ограничилась просто особо агрессивным ворчанием на тему политики и происходившего на войне."})}),(0,l.jsx)(h,{title:"Награды",children:(0,l.jsx)(n.p,{children:"Джулианну ждали награды за её службу. Увы, они были на имя Джона Конрада - и когда офицеры во время празднования Тет в Хюэ узнали правду об этом солдате, они предпочли поднять другую тему. Большинство празднование не пережили, а пережившим уже было не до этого дела - потому награды дошли до неё лишь посмертно. Во всех смыслах: шкатулку с её наградами она получила в подарок на 49 день рождения в Энкраже."})}),(0,l.jsx)(h,{title:"Список наград",children:(0,l.jsx)(n.p,{children:'Награды: Медаль "За службу во Вьетнаме", медаль "За безупречную службу", Похвальная медаль военно-морского флота США с кластером V, "Пурпурное сердце", Южновьетнамский крест "За храбрость", южновьетнамский орден "За выдающиеся заслуги" и, что было неожиданно для самой Джулианны, Медаль Почёта.'})}),(0,l.jsx)(h,{title:"Курение",children:(0,l.jsx)(n.p,{children:'Она относительно недавно начала курить в отчаянной попытке подавить свою раздражительность - всего-то в 2011 году. Ключи очень часто уходят на запасные зажигалки, пачки "Лаки Страйка" или на хорошую кубинскую сигару. Впрочем, дымит она не особо часто.'})}),(0,l.jsx)(h,{title:"Сокрытие информации",children:(0,l.jsx)(n.p,{children:'Информация с медосмотров Джулианны на фронте, равно как и остальные доказательства её нахождения там, укрывались одним из штабных командиров, подкупленным мафией. Он часто связывался с Хопкинсом, надеясь использовать информацию о её успехах как аргумент против "Проекта 100 000".'})}),(0,l.jsx)(h,{title:"Оружие во Вьетнаме",children:(0,l.jsx)(n.p,{children:"Основным оружием Джулианны в войне до 1967 года была винтовка М14, после - М16А1. Однако, в ходе войны ей пришлось пользоваться хотя бы раз гораздо более широким списком оружия: Кольт М1911А1, Кольт Детектив Спешиал, М1А1 Томпсон, карабин М1, Итака 37, М60, Пистолет Макарова, ППС-43, Тип-56 и Стоунер М63, а так же различные гранаты и оружие ближнего боя."})}),(0,l.jsx)(h,{title:"Kill count",children:(0,l.jsx)(n.p,{children:"Kill count: 236 подтверждённых + 17 неподтверждённых.\nПодтверждённые: 87 партизан Вьетконга, 113 солдат Северовьетнамской Армии, 36 мирных жителей (засчитаны в официальном рапорте как агенты Вьетконга).\nНеподтверждённые: 11 партизан Вьетконга (во время побега из плена), 6 мирных жителей (дети)."})})]})}),(0,l.jsx)(r,{title:"Внешность",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:'Если, смотря на нынешнюю Джулианну, вы решите что такой она была и при жизни - вы сильно ошибётесь. Пожалуй, из общего остались лишь общие пропорции тела, черты лица, да шрамы. Мантикоры нередко меняются ещё в самой башне под гнётом своего же ужасающего прошлого. Уже упоминалось, что из-за своих болей она чувствует себя старой? И не только из-за болей - война та хоть и длилась всего лишь пять лет для девушки, но из-за множества потерь и неприятных событий, казалось, она шла уже бесконечно. Это нашло своё отражение в её нынешнем облике - её теперь уже длинные волосы седы, словно стали такими от ужасов войны, за исключением двух медных прядей по бокам от чёлки. Волосы эти завязаны в довольно толстую косу. У Джилл цел лишь один глаз - янтарный. На месте второго - повязка с медного цвета трещинами. Это не узор - там, где видны медного цвета линии, действительно имеются небольшие углубления. Эту повязку нельзя снять с девушки - она уже стала частью её тела при формировании ядра. Однако, её можно приподнять - и под ней будет видно чёрное, гниющее месиво вокруг дыры. В ней иногда заметны некие медные разряды, нити некой энергии, проскальзывающие то тут, то там. Сверху и снизу от повязки на коже остался след - но не от одного пореза, от нескольких. Некоторые детали внешности здесь, в Энкраже, были явно преувеличены. Что янтарный глаз, что трещины начинают мерцать, когда Джулианна начинает злиться - и полноценно подсвечиваться, когда она уже на грани входа в "режим берсерка". Зрачок к тому времени начинает сужаться - но кто обращает уже на такую мелкую деталь внимание?'}),(0,l.jsx)(n.p,{children:"Что тогда, при жизни, что сейчас Джилл может стоять наравне со многими парнями - метр семьдесят девять рост этому способствует. Капрал, впрочем, отличается не только высоким ростом, но и спортивным телосложением - если не на учебке, так на войне мышечная масса волей-неволей да наберётся, а лишний вес сбросится. Её светлая кожа после смерти уже не тронута тем же загаром, что был у неё во Вьетнаме - но от этого девушка не становится менее внушительной внешне. В какой-то мере ей внушительности добавляют и острые клыки, подобные кошачьим. Впрочем, несмотря на спортивное телосложение, фигура Джилл довольно женственна - её не просто так очень быстро раскрывали все, кому было не лень. И кто, конечно же, её видел в числе солдат."}),(0,l.jsx)(n.p,{children:"Кто её видел в облике мантикоры? Никто, даже она сама. Ей ещё ни разу не приходилось обращаться в полноценного зверя - она даже не задумывалась о такой возможности. А в таком облике она - огромная пума-альбинос. Всё с той же неизменной повязкой на правом глазу, с белыми, маленькими крылышками, что скорее служат подвижной декорацией, и длинным белым хвостом, схожим со скорпионьим. Но шипов на нём огромное множество. Ядовитых шипов."}),(0,l.jsx)(n.p,{children:"Что касается одежды - она носит ту же форму, что у неё была во времена учебки. Но поверх неё - чёрный плащ с рукавами, тремя кустарными креплениями для запасных магазинов к М16, кустарными наплечниками, защищающими от ударов или небольших, перочинных ножей, и декоративными тканевыми наручами янтарного цвета. На руках она носит чёрные кожаные перчатки. Комплект обычно надевается так, что сервоприводы идут поверх плаща, а бронежилет - под ним, и соединяется это при помощи особых отверстий на молнии под кустарными наплечниками, но при особом желании Джилл может под плащом носить весь комплект в виду его дизайна, позволяющего при необходимости скрытое ношение. На ногах у неё имеются наколенники - они немного помогают при падениях. На её левой руке так же повязана красная ленточка - ей Джулианна даёт знать, что она работает на Хранителя. Правда, это далеко не официальный знак, его она придумала сама, и о его значении Хранитель далеко не факт что знает."})]})}),(0,l.jsx)(r,{title:"Навыки и умения",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Физическая подготовка",children:(0,l.jsx)(n.p,{children:"Будучи не просто мантикорой, но и солдатом, Джулианна отличается высокой физической силой, ловкостью, стойкостью и выносливостью."})}),(0,l.jsx)(h,{title:"Стрельба",children:(0,l.jsx)(n.p,{children:"Джилл, по той же причине, хорошо обращается с огнестрельным оружием времён войны во Вьетнаме — и может даже справиться с тем, что посовременнее, пускай, с ним опыта она не имеет. Список видов довольно широк и, по большей части, соответствует такому у современного оружия. Но с оптикой всё-таки она не дружит - по понятным причинам, да и точность стрельбы в целом омрачается из-за нехватки глаза, коим удобно целиться. А левым глазом с правого плеча… Это особое извращение. Но в отдельных случаях пользуется."})}),(0,l.jsx)(h,{title:"Метание гранат",children:(0,l.jsx)(n.p,{children:"Она прекрасно метает гранаты."})}),(0,l.jsx)(h,{title:"Ближний бой",children:(0,l.jsx)(n.p,{children:"Навыки ближнего боя, в том числе рукопашного, ножевого и штыкового. Не раз спасали жизнь Джулианны в джунглях, помогли ей сбежать из плена."})}),(0,l.jsx)(h,{title:"Кулинария",children:(0,l.jsx)(n.p,{children:"Неплохо готовит. Когда ей не лень."})}),(0,l.jsx)(h,{title:"Первая помощь",children:(0,l.jsx)(n.p,{children:"Может оказать первую помощь."})}),(0,l.jsx)(h,{title:"Высокий болевой порог",children:(0,l.jsx)(n.p,{children:"Нужно постараться чтобы заставить этот крепкий орешек расколоться и заставить кричать от боли."})}),(0,l.jsx)(h,{title:"Внимательность",children:(0,l.jsx)(n.p,{children:"Она внимательна, несмотря на отсутствие правого глаза, хорошо подмечает мельчайшие детали. Заметить проволоку посреди зарослей, осторожно обезвредить растяжку для остальных — без этого в джунглях трудно выжить."})}),(0,l.jsx)(h,{title:"Обезвреживание ловушек",children:(0,l.jsx)(n.p,{children:'Обезвреживание простейших ловушек и работа с противопехотными минами М18А1 "Клеймор".'})})]})}),(0,l.jsx)(r,{title:"Слабости",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Отсутствие правого глаза",children:(0,l.jsx)(n.p,{children:"Само по себе оно бы не было так критично, но Джилл — правша, что делает полноценное прицеливание невозможным."})}),(0,l.jsx)(h,{title:"Без комплекта (боли)",children:(0,l.jsx)(n.p,{children:"Без комплекта — подверженность болям, онемениям, в редчайших случаях параличам."})}),(0,l.jsx)(h,{title:"Без комплекта (берсерк)",children:(0,l.jsx)(n.p,{children:"Без комплекта — режим берсерка серьёзно изнашивает ядро девушки, что может привести как к сильнейшей усталости, так и к полноценному обмороку. Или даже смерти."})}),(0,l.jsx)(h,{title:"Без комплекта (магия)",children:(0,l.jsx)(n.p,{children:"Без комплекта — отсутствие каких-либо магических способностей и возможности их развития."})}),(0,l.jsx)(h,{title:"С комплектом (блокировка берсерка)",children:(0,l.jsx)(n.p,{children:"С комплектом — полная блокировка режима берсерка, за исключением, конечно же, душевного состояния."})}),(0,l.jsx)(h,{title:"С комплектом (нагрузка)",children:(0,l.jsx)(n.p,{children:"С комплектом — высокая нагрузка на ядро, что приводит к осложнению точной стрельбы из оружия (отмечу, что значительность проблем с точностью уменьшается с уменьшением расстояния до цели и с увеличением её размеров)."})}),(0,l.jsx)(h,{title:"Уязвимость правого глаза",children:(0,l.jsx)(n.p,{children:"Правый глаз, вернее, то, что от него осталось, очень уязвим для колющего оружия и снарядов."})}),(0,l.jsx)(h,{title:"Медленное восстановление энергии",children:(0,l.jsx)(n.p,{children:"Медленное восстановление энергии."})}),(0,l.jsx)(h,{title:"Неспособность к обращению",children:(0,l.jsx)(n.p,{children:"Неспособность (на данный момент) принять звериный облик."})}),(0,l.jsx)(h,{title:"ПТСР",children:(0,l.jsx)(n.p,{children:"ПТСР."})}),(0,l.jsx)(h,{title:"Эмоциональная нестабильность",children:(0,l.jsx)(n.p,{children:"Общая эмоциональная нестабильность."})}),(0,l.jsx)(h,{title:"Сопротивление положительной магии",children:(0,l.jsx)(n.p,{children:'Какие-либо сторонние положительные магические эффекты на мантикору действуют слабее. В том числе и лечение. См. сопротивление магии. Небольшим "бонусом" будет головная боль для Джулианны — и все мы знаем, что это её бесит. Эти эффекты ослабляются значительно, значительно сильнее отрицательных — аж на 90%.'})})]})}),(0,l.jsx)(r,{title:"Оружие",children:(0,l.jsx)(d,{children:(0,l.jsx)(h,{title:"Ka-Bar USMC",children:(0,l.jsx)(n.p,{children:"Связанный Ka-Bar USMC. Длина клинка — 18 см, общая длина — 30 см. Простой и удобный нож служит не только связанным предметом, но и хорошим оружием последнего шанса."})})})}),(0,l.jsx)(r,{title:"Связанные персонажи",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Генри Мэйсон",children:(0,l.jsx)(n.p,{children:"Людской мир. Отец Джилл. Связан немецкой металлической фляжкой, подаренной им, когда она была ещё маленькой. Чаще всего там виски. Джек Дэниэлс."})}),(0,l.jsx)(h,{title:"Уилл Стоун",children:(0,l.jsx)(n.p,{children:"Людской мир. Сержант отряда Джилл. Связан его ножом Ka-Bar, что она хранила после его гибели."})})]})})]}),(0,l.jsx)(x,{children:(0,l.jsx)(n.p,{children:"Я и моя винтовка знаем, на что идёт счет в этой войне — не на количество застреленных нами патронов, не на грохот наших выстрелов и не на пороховой дым. Мы знаем, что счёт будет вестись только на убитых. И мы будем убивать"})})]})}function s(e,l){throw Error("Expected "+(l?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,i.useMDXComponents)(),...e.components};return s?(0,l.jsx)(s,{...e,children:(0,l.jsx)(n,{...e})}):n(e)}])}]);